 async function print(){if(!page())return;try{const win=window.open('','_blank');if(!win)throw Error('Permita abrir a janela de impressão.');win.document.write('<!doctype html><title>Notas</title><p>Preparando página…</p>');const {w,h}=dimensions();const objects=page().objects.map(o=>JSON.parse(JSON.stringify(o)));const content=[];for(const o of objects){let inner=o.type==='table'?tableHTML(o,true):o.type==='text'?`<div style="white-space:pre-wrap;font:${o.bold?'bold ':''}${o.fontSize}px system-ui;color:${o.color}">${checklistHTML(o,true)}</div>`:o.type==='image'?`<img style="width:100%;height:100%;object-fit:contain" src="data:${o.mime};base64,${(await NotesData.resolveAsset(o)).base64}" alt="${esc(o.caption)}">`:lineSVG(o);content.push(`<div style="position:absolute;left:${o.x}px;top:${o.y}px;width:${o.w}px;height:${o.h}px;transform:rotate(${o.rotation}deg)">${inner}</div>`)}const usedW=Math.max(600,...objects.map(o=>o.x+o.w+30)),usedH=Math.max(300,...objects.map(o=>o.y+o.h+30));win.document.body.innerHTML=`<h1>${esc(page().title)}</h1><div style="${NotesData.paperStyle(page())}position:relative;width:${usedW}px;height:${usedH}px">${content.join('')}</div>`;const style=win.document.createElement('style');style.textContent=`body{margin:20px;color:#25364a}h1{font:24px system-ui;margin:0 0 20px}@media print{@page{size:landscape;margin:10mm}body{zoom:${Math.min(1,1000/usedW)}}}`;win.document.head.append(style);await Promise.all([...win.document.images].map(i=>i.decode().catch(()=>{})));win.focus();win.print()}catch(e){status(e.message,true)}}
